package com.learnspherex.payment;
import java.math.*; import java.time.*; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="payments") @Getter @NoArgsConstructor @EqualsAndHashCode(of="id") public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long studentUserId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="installment_id",nullable=false) private Installment installment; @Column(nullable=false,precision=12,scale=2) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentMethod method; @Enumerated(EnumType.STRING) @Column(nullable=false) private PaymentStatus status; @Column(unique=true,length=80) private String transactionReference; @Column(nullable=false) private Instant paidAt; @OneToOne(mappedBy="payment",cascade=CascadeType.ALL) private PaymentReceipt receipt; public Payment(Long s,Installment i,BigDecimal a,PaymentMethod m,String ref){studentUserId=s;installment=i;amount=a;method=m;transactionReference=ref;status=PaymentStatus.PAID;paidAt=Instant.now();} public void attachReceipt(PaymentReceipt r){receipt=r;} }
